<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch,nextTick } from 'vue';
import { useDisplay } from '../../shared/useDisplay';
import { type Row,formatTime } from '../../shared/domain';
import { api,uploadMedia } from '../api';
const mediaUrl=(id:string)=>'/api/media/'+encodeURIComponent(id);
const props=defineProps<{user:Row|null}>();
const active=ref(!document.hidden),stage=ref<HTMLElement|null>(null),player=ref<HTMLVideoElement|null>(null),full=ref(false);
const {data,error,message,mediaError,loading,busy,paused,index,managing,assets,editing,removing,form,uploading,uploadProgress,staff,slides,current,maxMonth,maxCategory,next,failed,load,manage,edit,upload,save}=useDisplay(()=>props.user,api,()=>active.value);
async function select(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(!/\.(mp4|png|jpe?g)$/i.test(file.name)){error.value='请选择JPG、PNG照片或MP4视频';return;}await upload(progress=>uploadMedia(file,'display','',progress));}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await stage.value?.requestFullscreen();}catch{error.value='此浏览器不支持全屏，可使用横屏或浏览器全屏模式。';}}
function visibility(){active.value=!document.hidden;}
function fullChanged(){full.value=!!document.fullscreenElement;}
watch([paused,current,active],async()=>{await nextTick();const video=player.value;if(!video)return;if(paused.value||!active.value)video.pause();else try{await video.play();}catch{mediaError.value='自动播放被浏览器限制，请点击视频播放按钮。';}},{flush:'post'});
onMounted(()=>{document.addEventListener('visibilitychange',visibility);document.addEventListener('fullscreenchange',fullChanged);});onUnmounted(()=>{document.removeEventListener('visibilitychange',visibility);document.removeEventListener('fullscreenchange',fullChanged);});
</script>
<template>
 <section class="display-hub"><div class="feature-actions display-toolbar"><button class="primary" @click="fullscreen">{{full?'退出全屏':'全屏展示'}}</button><button class="outline" :disabled="loading" @click="load">刷新数据</button><button v-if="staff" class="outline" @click="manage">管理播放素材</button><span class="feature-muted">每分钟自动更新 · 不含个人联系方式</span></div><p v-if="error" class="feature-error" role="alert">{{error}}</p><p v-if="message" class="feature-success">{{message}}</p>
  <div ref="stage" class="display-stage"><header class="display-header"><div><p>SHUYANG HOME · 乡情相聚</p><h2>沭阳之家<span>每一份参与，都有回响。</span></h2></div><div class="display-stamp"><span class="display-live"></span>{{loading?'正在更新':data?'已连接':'等待数据'}}<p v-if="data">更新于 {{formatTime(data.updatedAt)}}</p><button v-if="full" class="stage-button" @click="fullscreen">退出全屏</button></div></header>
   <div v-if="!data" class="display-placeholder">{{error?'数据暂不可用，请刷新重试。':'正在连接乡情看板…'}}</div>
   <template v-else><div class="display-metrics"><div><span>已加入的家人</span><strong>{{data.members}}<small>人</small></strong></div><div><span>已发布活动</span><strong>{{data.events}}<small>场</small></strong></div><div><span>已核定志愿服务</span><strong>{{data.hours}}<small>小时</small></strong></div></div>
    <div class="display-layout"><section class="display-media"><div class="display-media-frame"><template v-if="current"><img v-if="current.type==='image'" :src="mediaUrl(current.mediaId)" :alt="current.title" @error="failed"><video v-else :key="current.mediaId" ref="player" :src="mediaUrl(current.mediaId)" autoplay muted playsinline controls :loop="slides.length===1" preload="metadata" @ended="!paused&&next()" @error="failed"/><div class="display-caption"><b>{{current.title}}</b><span>{{current.caption}}</span></div></template><div v-else class="display-placeholder"><span class="display-home-mark">家</span><h3>乡音相连，温暖同行。</h3><p>照片与视频发布后，在这里一起回看。</p></div></div><div class="display-play-controls"><button class="stage-button" :disabled="!slides.length" @click="next(-1)">上一条</button><button class="stage-button" :disabled="!slides.length" :aria-pressed="paused" @click="paused=!paused">{{paused?'继续播放':'暂停轮播'}}</button><span>{{slides.length?index+1:0}} / {{slides.length}}</span><button class="stage-button" :disabled="!slides.length" @click="next()">下一条</button></div><p v-if="mediaError" class="display-media-error" role="status">{{mediaError}}</p></section>
    <aside class="display-charts"><section><h3>近六个月 · 相聚足迹</h3><p class="display-chart-note">按已发布活动的开始月份统计</p><div class="display-columns" role="img" aria-label="近六个月活动数量"><div v-for="month in data.months" :key="month.label"><b>{{month.value}}</b><div class="display-column-space"><span :style="{height:Math.max(2,month.value/maxMonth*100)+'%'}"></span></div><small>{{month.label.slice(5)}}月</small></div></div></section><section><h3>活动类型</h3><div v-for="category in data.categories" :key="category.label" class="display-bar"><div><span>{{category.label||'其他'}}</span><b>{{category.value}} 场</b></div><div class="display-bar-track"><span :style="{width:category.value/maxCategory*100+'%'}"></span></div></div><p v-if="!data.categories.length" class="display-chart-note">首场活动发布后，这里会留下足迹。</p></section></aside></div>
    <footer class="display-upcoming"><strong>下一次相聚</strong><div v-for="event in data.upcoming" :key="event.id"><b>{{event.title}}</b><span>{{formatTime(event.startsAt)}} · {{event.location}}</span></div><span v-if="!data.upcoming.length">新的活动正在酝酿，期待与你相见。</span></footer>
   </template>
  </div>
  <section v-if="managing&&staff" class="feature-card display-management"><div class="feature-heading"><h3>播放素材</h3><button class="outline" :disabled="busy||uploading" @click="managing=false;editing=false">收起管理</button></div><p class="feature-muted">JPG／PNG照片最多8MB，MP4视频最多15MB，建议H.264编码。视频按原时长播放，照片按设置秒数轮播；数字小的先播放。</p><button class="primary" :disabled="busy||uploading" @click="edit()">新增照片／视频</button>
   <form v-if="editing" class="display-form" @submit.prevent="save()"><label>标题<input v-model="form.title" maxlength="80" minlength="2" required></label><label>说明<textarea v-model="form.caption" maxlength="300"></textarea></label><label>照片或视频<input type="file" accept="image/jpeg,image/png,video/mp4,.mp4" :disabled="busy||uploading" @change="select"></label><p>{{uploading?'上传中 '+uploadProgress+'%':form.mediaId?'已选择：'+(form.mediaName||form.type):'请上传一份素材'}}</p><label>播放顺序<input v-model="form.position" type="number" min="0" max="999" required></label><label>照片停留秒数<input v-model="form.seconds" type="number" min="5" max="60" required></label><label>展示状态<select v-model="form.status"><option value="draft">草稿，仅管理人员可见</option><option value="published">公开展示</option></select></label><label class="feature-check"><input v-model="form.consent" type="checkbox">已确认拥有素材展示权限，内容适合公开展示</label><div class="feature-actions"><button class="primary" :disabled="busy||uploading||!form.mediaId">保存素材</button><button type="button" class="outline" :disabled="busy||uploading" @click="editing=false">取消</button></div></form>
   <div v-if="removing" class="feature-error">确认移除“{{removing.title}}”？<div class="feature-actions"><button class="primary" :disabled="busy" @click="save(true)">确认移除</button><button class="outline" @click="removing=null">取消</button></div></div><div v-for="asset in assets" :key="asset.id" class="display-asset"><div><b>{{asset.position}} · {{asset.title}}</b><p>{{asset.type==='video'?'视频':'照片'}} · {{asset.status==='published'?'公开展示':'草稿'}}</p></div><div class="feature-actions"><button class="outline" :disabled="busy||uploading" @click="edit(asset)">编辑</button><button class="text-button" :disabled="busy||uploading" @click="removing=asset">移除</button></div></div><p v-if="!assets.length" class="feature-empty">还没有素材，上传第一张活动照片吧。</p>
  </section>
 </section>
</template>
<style scoped src="../../shared/people-display.css"></style>
